// Tests for Breakout Time Frame Confirmation (BreakoutTfEngine + breakoutTfFetch).
// ALL candle data here is generated by fixed formulas and every provider answer is a
// MOCK. Nothing in this file contacts Dhan or any network, so none of it verifies the
// real provider; see the report for what is and is not verified.
// Run: node --test tests/breakout-tf.test.mjs
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import crypto from "node:crypto";
import {
  BTF, TIMEFRAMES, INSTRUMENTS, evaluateBreakoutTf, analyseFrame, validateCandles, levelAndBreakout, trendOf,
  expectedLastEnd, freshnessOf, isTradingDayIndex, istLabel
} from "../src/screens/BreakoutTfEngine.js";
import { loadFrame, loadFrames, frameFromResponse, clearFrameCache, buildRange } from "../src/services/breakoutTfFetch.js";
import { computeDirection } from "../src/screens/DirectionEngine.js";
import { computeNextMove } from "../src/screens/NextMoveEngine.js";
import { makePayload, makeBars } from "./direction-fixtures.mjs";

function read(f){ return fs.readFileSync(new URL("../" + f, import.meta.url), "utf8"); }
var DAY = 86400000, IST = 19800000;
// Tuesday 2026-10-13 12:00:30 IST (session open, no holiday)
var NOW = Date.UTC(2026, 9, 13, 6, 30, 30);
var NIFTY = "NIFTY";

// ---- fixture builders --------------------------------------------------------
// Session-aligned candle starts for a timeframe, oldest first, ending before limitMs.
function startsBefore(tfKey, limitMs, count){
  var tf = TIMEFRAMES[tfKey], out = [];
  var day = Math.floor((limitMs + IST) / DAY);
  var guard = 0;
  while(out.length < count && guard < 400){
    if(isTradingDayIndex(day)){
      var open = day * DAY - IST + BTF.OPEN_MIN * 60000, close = day * DAY - IST + BTF.CLOSE_MIN * 60000;
      var list = [];
      if(tf.minutes == null) list.push(open);
      else { for(var s = open; s < close; s += tf.minutes * 60000) list.push(s); }
      for(var i = list.length - 1; i >= 0 && out.length < count; i--){ if(list[i] < limitMs) out.push(list[i]); }
    }
    day--; guard++;
  }
  return out.reverse();
}
function endOf(tfKey, startMs){
  var tf = TIMEFRAMES[tfKey];
  var day = Math.floor((startMs + IST) / DAY), close = day * DAY - IST + BTF.CLOSE_MIN * 60000;
  return tf.minutes == null ? close : Math.min(startMs + tf.minutes * 60000, close);
}
// shape(i, n) -> close price; candles built open=prev close, small wicks
function candles(tfKey, n, shape, opts){
  opts = opts || {};
  var now = opts.now || NOW;
  // completed candles only: end <= now. Provisional candle appended when asked.
  var starts = startsBefore(tfKey, now + 1, n + 6).filter(function(s){ return endOf(tfKey, s) <= now - (opts.shiftMs || 0); }).slice(-n);
  var out = [], prev = shape(0, n);
  starts.forEach(function(s, i){
    var c = shape(i, n), o = prev, hi = Math.max(o, c) + 0.5, lo = Math.min(o, c) - 0.5;
    if(opts.wick && i == n - 1){ hi = opts.wick; }
    out.push({ time:s / 1000, timestamp:"x", open:o, high:hi, low:lo, close:c, volume:1000 });
    prev = c;
  });
  if(opts.provisional){
    var ps = startsBefore(tfKey, now + 1, 1)[0];
    var all = startsBefore(tfKey, now + 1, 3);
    var cur = all[all.length - 1];
    if(cur != null && endOf(tfKey, cur) > now && (!out.length || out[out.length - 1].time * 1000 < cur)){
      out.push({ time:cur / 1000, timestamp:"x", open:100, high:opts.provisional + 0.5, low:99, close:opts.provisional, volume:10 });
    }
    void ps;
  }
  return out;
}
var wave = [0, 1.2, 0.4, -1.1, -0.3, 1.0, -0.8, 0.6];
function flatThenBreak(dir){ return function(i, n){ if(i >= n - 2) return 100 + dir * 12 + dir * (i - (n - 2)); return 100 + wave[i % wave.length]; }; }
function up(i){ return 100 + i * 0.6 + wave[i % wave.length] * 0.2; }
function down(i, n){ return 100 + (n - i) * 0.6 + wave[i % wave.length] * 0.2; }
function frame(symbol, tfKey, cs){
  return { ok:true, fetchedAt:NOW, candles:cs, meta:{ source:"dhan", symbol:symbol, exchangeSegment:"IDX_I", timeframe:TIMEFRAMES[tfKey].interval, timezone:"Asia/Kolkata", dataStatus:"PROVIDER_HISTORICAL" } };
}
function ev(tfKey, frames, extra){ return evaluateBreakoutTf(Object.assign({ symbol:NIFTY, tf:tfKey, frames:frames, now:NOW }, extra || {})); }
function keys(v){ return v.reasons.map(function(r){ return r.key; }); }

// 15m breakout with 1H and 1D trends as given
function scenario(dir, h1Trend, d1Trend){
  var shape = { up:up, down:down };
  return {
    "15m": frame(NIFTY, "15m", candles("15m", 40, flatThenBreak(dir))),
    "1H":  frame(NIFTY, "1H",  candles("1H", 40, shape[h1Trend])),
    "1D":  frame(NIFTY, "1D",  candles("1D", 40, shape[d1Trend]))
  };
}

// ---- 1, 2 valid breakout / breakdown with agreeing higher timeframes ------------
test("1. bullish breakout, 1H and Daily trends agree -> confirmed bullish", function(){
  var v = ev("15m", scenario(1, "up", "up"));
  assert.equal(v.state, "confirmed"); assert.equal(v.direction, "bullish");
  assert.equal(v.conflicts.length, 0); assert.equal(v.htfSummary.agree, 2);
  assert.ok(v.level.resistance < v.selected.last.close);
  assert.ok(v.lastCandle && v.lastCandle.completed == true);
});
test("2. bearish breakdown, 1H and Daily trends agree -> confirmed bearish", function(){
  var v = ev("15m", scenario(-1, "down", "down"));
  assert.equal(v.state, "confirmed"); assert.equal(v.direction, "bearish");
  assert.ok(v.level.support > v.selected.last.close);
});
test("2b. every documented pairing works (5m, 1H, Daily)", function(){
  var f5 = { "5m":frame(NIFTY, "5m", candles("5m", 60, flatThenBreak(1))), "15m":frame(NIFTY, "15m", candles("15m", 40, up)), "1H":frame(NIFTY, "1H", candles("1H", 40, up)) };
  assert.equal(ev("5m", f5).state, "confirmed");
  var f1 = { "1H":frame(NIFTY, "1H", candles("1H", 40, flatThenBreak(1))), "1D":frame(NIFTY, "1D", candles("1D", 40, up)) };
  assert.equal(ev("1H", f1).state, "confirmed");
});
test("2c. Daily has no required higher timeframe (no weekly source): daily alone, said plainly", function(){
  var v = ev("1D", { "1D":frame(NIFTY, "1D", candles("1D", 40, flatThenBreak(1))) });
  assert.equal(v.htfRequired, 0); assert.equal(v.higher.length, 0);
  assert.equal(v.state, "confirmed"); assert.ok(keys(v).indexOf("bt.r.daily_only") >= 0);
});

// ---- 3 conflict ---------------------------------------------------------------
test("3. selected breakout up but 1H trend down -> conflicting, never confirmed", function(){
  var v = ev("15m", scenario(1, "down", "up"));
  assert.equal(v.state, "conflicting"); assert.equal(v.conflicts.length, 1); assert.equal(v.conflicts[0].tf, "1H");
  var v2 = ev("15m", scenario(-1, "up", "up"));
  assert.equal(v2.state, "conflicting"); assert.equal(v2.conflicts.length, 2);
});
test("3b. an opposite higher trend is listed as a conflict even while still waiting", function(){
  var f = scenario(1, "down", "down");
  f["15m"] = frame(NIFTY, "15m", candles("15m", 40, function(i, n){ return i == n - 1 ? 112 : 100 + wave[i % wave.length]; }));
  var v = ev("15m", f);
  assert.equal(v.state, "waiting"); assert.ok(v.conflicts.length >= 1);
});

// ---- 4 touch / wick / forming candle never confirm ----------------------------
test("4. price touches the level but the completed candle closes inside -> waiting, no breakout", function(){
  var f = scenario(1, "up", "up");
  var base = candles("15m", 40, function(i){ return 100 + wave[i % wave.length]; });
  var lvl = levelAndBreakout(validateCandles(base, "15m", NOW).candidates || validateCandles(base, "15m", NOW).candles, null).resistance;
  var touched = candles("15m", 40, function(i){ return 100 + wave[i % wave.length]; }, { wick:lvl + 5 });
  f["15m"] = frame(NIFTY, "15m", touched);
  var v = ev("15m", f);
  assert.equal(v.state, "waiting"); assert.equal(v.direction, "none");
  assert.ok(keys(v).indexOf("bt.r.touch_up") >= 0, keys(v).join(","));
});
test("4b. one completed close beyond the level is only 'early' -> waiting", function(){
  var f = scenario(1, "up", "up");
  f["15m"] = frame(NIFTY, "15m", candles("15m", 40, function(i, n){ return i == n - 1 ? 115 : 100 + wave[i % wave.length]; }));
  var v = ev("15m", f);
  assert.equal(v.state, "waiting"); assert.equal(v.direction, "none"); assert.equal(v.candidateDirection, "bullish");
  assert.ok(keys(v).indexOf("bt.r.early_up") >= 0);
});
test("4c. a forming candle beyond the level is shown but never counted", function(){
  var f = scenario(1, "up", "up");
  f["15m"] = frame(NIFTY, "15m", candles("15m", 40, function(i){ return 100 + wave[i % wave.length]; }, { provisional:130 }));
  var v = ev("15m", f);
  assert.equal(v.state, "waiting");
  assert.ok(v.provisionalCandle && v.provisionalCandle.completed == false, "provisional candle is labelled");
  assert.ok(keys(v).indexOf("bt.r.forming") >= 0);
  assert.equal(v.selected.completed, 40, "provisional is not among completed bars");
});

// ---- 5 missing data ----------------------------------------------------------
test("5. missing higher timeframe -> unconfirmed, never confirmed; missing selected -> unavailable", function(){
  var f = scenario(1, "up", "up"); delete f["1D"];
  var v = ev("15m", f);
  assert.equal(v.state, "unconfirmed"); assert.equal(v.higher[1].status, "unavailable");
  assert.ok(keys(v).indexOf("bt.r.htf_missing") >= 0);
  var g = scenario(1, "up", "up"); delete g["15m"];
  var w = ev("15m", g);
  assert.equal(w.state, "unavailable"); assert.equal(w.direction, "none"); assert.equal(w.level, null);
});
test("5b. a neutral higher timeframe cannot confirm", function(){
  var f = scenario(1, "up", "up");
  f["1H"] = frame(NIFTY, "1H", candles("1H", 40, function(i){ return 100 + wave[i % wave.length]; }));
  var v = ev("15m", f);
  assert.equal(v.state, "unconfirmed"); assert.ok(keys(v).indexOf("bt.r.htf_neutral") >= 0);
});

// ---- 6 stale and future data ---------------------------------------------------
test("6. stale selected data (last candle 3 hours old) -> unavailable", function(){
  var f = scenario(1, "up", "up");
  f["15m"] = frame(NIFTY, "15m", candles("15m", 40, flatThenBreak(1), { shiftMs:3 * 3600000 }));
  var v = ev("15m", f);
  assert.equal(v.state, "unavailable"); assert.equal(v.selected.status, "stale"); assert.equal(v.direction, "none");
});
test("6b. stale higher timeframe cannot be used for confirmation", function(){
  var f = scenario(1, "up", "up");
  f["1D"] = frame(NIFTY, "1D", candles("1D", 40, up, { shiftMs:6 * DAY }));
  var v = ev("15m", f);
  assert.equal(v.state, "unconfirmed"); assert.equal(v.higher[1].status, "stale");
});
test("6c. freshness: previous candle is accepted only inside the provider grace period", function(){
  var e = expectedLastEnd("15m", NOW);
  assert.equal(istLabel(e), "13 Oct 2026, 12:00 IST");
  var prev = e - 15 * 60000;
  assert.equal(freshnessOf("15m", e, NOW).state, "fresh");
  assert.equal(freshnessOf("15m", prev, e + 60000).state, "fresh", "within grace");
  assert.equal(freshnessOf("15m", prev, e + 20 * 60000).state, "stale", "beyond grace");
  assert.equal(freshnessOf("15m", prev, e + 20 * 60000).lagMs, 30 * 60000, "expected end moved on by one candle");
});
test("6d. future-dated candles are rejected, not treated as current", function(){
  var cs = candles("15m", 40, flatThenBreak(1));
  var fut = cs[cs.length - 1].time + 3 * 3600;
  cs.push({ time:fut, open:100, high:101, low:99, close:100.5, volume:1 });
  var v = validateCandles(cs, "15m", NOW);
  assert.equal(v.rejected.future, 1); assert.equal(v.candles.length, 40);
});
test("6e. after the close and over a weekend the last session is fresh, a missed session is stale", function(){
  var satNow = Date.UTC(2026, 9, 17, 6, 0, 0);          // Saturday 11:30 IST
  assert.equal(istLabel(expectedLastEnd("1D", satNow)), "16 Oct 2026, 15:30 IST");
  assert.equal(istLabel(expectedLastEnd("15m", satNow)), "16 Oct 2026, 15:30 IST");
  var fri = Date.UTC(2026, 9, 16, 10, 0, 0);            // Fri 15:30 IST exactly
  assert.equal(freshnessOf("1D", fri, satNow).state, "fresh");
  assert.equal(freshnessOf("1D", fri - 2 * DAY, satNow).state, "stale");
});

// ---- 7 insufficient history ------------------------------------------------------
test("7. insufficient selected history -> unavailable (never a breakout)", function(){
  var f = scenario(1, "up", "up");
  f["15m"] = frame(NIFTY, "15m", candles("15m", 8, flatThenBreak(1)));
  var v = ev("15m", f);
  assert.equal(v.state, "unavailable"); assert.equal(v.selected.status, "insufficient"); assert.equal(v.selected.reasonVars.need, BTF.MIN_LEVEL_BARS);
});
test("7b. higher timeframe with fewer than 30 candles is 'insufficient' and cannot confirm", function(){
  var f = scenario(1, "up", "up");
  f["1H"] = frame(NIFTY, "1H", candles("1H", 20, up));
  var v = ev("15m", f);
  assert.equal(v.state, "unconfirmed"); assert.equal(v.higher[0].status, "insufficient"); assert.equal(v.higher[0].reasonVars.have, 20);
  assert.equal(trendOf([]).insufficient, true);
});

// ---- 8 malformed candles and invalid timestamps ------------------------------------
test("8. malformed candles and invalid timestamps are rejected and counted", function(){
  var good = candles("15m", 20, up);
  var t0 = good[good.length - 1].time;
  var bad = [
    null, "x", 5, {},
    { time:t0 + 900, open:"1", high:2, low:1, close:1.5, volume:1 },
    { time:t0 + 900, open:100, high:99, low:101, close:100, volume:1 },     // high < low
    { time:t0 + 900, open:100, high:101, low:99, close:NaN, volume:1 },
    { time:t0 + 900, open:-1, high:101, low:99, close:100, volume:1 },
    { time:t0 + 900, open:100, high:101, low:99, close:100, volume:-5 },
    { time:"1760000000", open:100, high:101, low:99, close:100, volume:1 },     // string time
    { time:1760000000.5, open:100, high:101, low:99, close:100, volume:1 },    // fractional
    { time:0, open:100, high:101, low:99, close:100, volume:1 },               // epoch zero
    { time:-100, open:100, high:101, low:99, close:100, volume:1 },
    { time:Infinity, open:100, high:101, low:99, close:100, volume:1 }
  ];
  var r = validateCandles(good.concat(bad), "15m", NOW);
  assert.equal(r.candles.length, 20);
  assert.equal(r.rejected.malformed, 9); assert.equal(r.rejected.badTime, 5);
  var f = scenario(1, "up", "up"); f["15m"] = frame(NIFTY, "15m", good.concat(bad));
  assert.equal(analyseFrame(f["15m"], "15m", "selected", NIFTY, NOW).rejected.malformed, 9);
});
test("8b. a response where every candle is invalid is unavailable, not empty-but-fine", function(){
  var f = frame(NIFTY, "15m", [{ time:"x" }, null, { time:1, open:1 }]);
  var a = analyseFrame(f, "15m", "selected", NIFTY, NOW);
  assert.equal(a.status, "unavailable"); assert.equal(a.reasonKey, "bt.tf.all_invalid");
});
test("8c. duplicates and unsorted rows are normalised", function(){
  var cs = candles("15m", 20, up);
  var shuffled = cs.slice().reverse().concat([cs[3]]);
  var r = validateCandles(shuffled, "15m", NOW);
  assert.equal(r.candles.length, 20); assert.equal(r.rejected.duplicate, 1);
  for(var i = 1; i < r.candles.length; i++) assert.ok(r.candles[i].t > r.candles[i - 1].t);
});

// ---- 9 provider error and missing credentials ------------------------------------------
test("9. provider error states map to an Unavailable view with a reason, never a fabricated fallback", function(){
  var cases = [
    [503, { ok:false, reason:"CREDENTIALS_MISSING", code:"token_missing", message:"DHAN_ACCESS_TOKEN is not set on the server." }, "bt.err.creds_missing"],
    [502, { ok:false, reason:"CREDENTIALS_INVALID", code:"token_format" }, "bt.err.creds_invalid"],
    [502, { ok:false, reason:"DATA_API_NOT_SUBSCRIBED" }, "bt.err.not_subscribed"],
    [429, { ok:false, reason:"RATE_LIMITED" }, "bt.err.rate_limited"],
    [504, { ok:false, reason:"TIMEOUT" }, "bt.err.timeout"],
    [502, { ok:false, reason:"PROVIDER_ERROR", code:"malformed_response" }, "bt.err.provider"],
    [500, null, "bt.err.provider"],
    [200, { ok:true, data:{ state:"EMPTY", candles:[] } }, "bt.err.empty"]
  ];
  cases.forEach(function(c){
    var fr = frameFromResponse(c[0], c[1], NOW);
    assert.equal(fr.ok, false);
    var v = ev("15m", { "15m":fr });
    assert.equal(v.state, "unavailable"); assert.equal(v.direction, "none"); assert.equal(v.level, null);
    assert.equal(v.reasons[0].key, c[2]);
  });
  var u = frameFromResponse(400, { ok:false, reason:"INVALID_INPUT", code:"invalid_timeframe" }, NOW);
  assert.equal(analyseFrame(u, "15m", "selected", NIFTY, NOW).status, "unsupported");
});
test("9b. credentials or secrets are never copied from a server message into the frame", function(){
  var fr = frameFromResponse(503, { ok:false, reason:"CREDENTIALS_MISSING", message:"secret-token-abc123" }, NOW);
  assert.equal(JSON.stringify(fr).indexOf("secret-token"), -1);
});
test("9c. loader: network failure, timeout abort and bad JSON become error frames", async function(){
  clearFrameCache();
  var r1 = await loadFrame(NIFTY, "15m", { now:NOW, fetchImpl:function(){ return Promise.reject(new Error("offline")); } });
  assert.equal(r1.error.code, "NETWORK");
  clearFrameCache();
  var r2 = await loadFrame(NIFTY, "15m", { now:NOW, fetchImpl:function(){ var e = new Error("x"); e.name = "AbortError"; return Promise.reject(e); } });
  assert.equal(r2.error.code, "TIMEOUT");
  clearFrameCache();
  var r3 = await loadFrame(NIFTY, "15m", { now:NOW, fetchImpl:function(){ return Promise.resolve({ status:200, json:function(){ return Promise.reject(new Error("bad")); } }); } });
  assert.equal(r3.error.code, "PROVIDER_ERROR");
  clearFrameCache();
});
test("9d. loader uses the existing route and the provider's own interval format; caches and shares calls", async function(){
  clearFrameCache();
  var calls = [];
  var body = { ok:true, data:{ state:"OK", source:"dhan", symbol:NIFTY, exchangeSegment:"IDX_I", timeframe:"60", timezone:"Asia/Kolkata", dataStatus:"PROVIDER_HISTORICAL", candles:candles("1H", 40, up) } };
  var impl = function(url){ calls.push(url); return Promise.resolve({ status:200, json:function(){ return Promise.resolve(body); } }); };
  var both = await Promise.all([loadFrame(NIFTY, "1H", { now:NOW, fetchImpl:impl }), loadFrame(NIFTY, "1H", { now:NOW, fetchImpl:impl })]);
  assert.equal(calls.length, 1, "identical in-flight requests share one call");
  var again = await loadFrame(NIFTY, "1H", { now:NOW + 5000, fetchImpl:impl });
  assert.equal(calls.length, 1, "valid cached candles are reused"); assert.equal(again.ok, true); assert.equal(both[0].ok, true);
  assert.ok(calls[0].indexOf("/api/market?action=historical") == 0);
  assert.ok(calls[0].indexOf("symbol=NIFTY") > 0 && calls[0].indexOf("timeframe=60") > 0);
  await loadFrame(NIFTY, "1H", { now:NOW + 5000, fetchImpl:impl, force:true });
  assert.equal(calls.length, 2, "refresh bypasses the cache");
  var multi = await loadFrames(NIFTY, "5m", { now:NOW, fetchImpl:impl });
  assert.deepEqual(Object.keys(multi).sort(), ["15m", "1H", "5m"].sort());
  clearFrameCache();
});
test("9e. request windows are dates the provider accepts (intraday <= 90 days, daily 'to' is tomorrow IST)", function(){
  var r = buildRange("1D", NOW);
  assert.equal(r.to, "2026-10-14");
  var r2 = buildRange("5m", NOW);
  assert.equal(r2.to, "2026-10-13");
  ["5m", "15m", "1H"].forEach(function(k){ var b = buildRange(k, NOW); assert.ok((Date.parse(b.to) - Date.parse(b.from)) / DAY <= 90); });
});

// ---- 10 exchange / session timezone ----------------------------------------------------
test("10. session timezone: candles must start inside 09:15-15:30 IST on an interval boundary", function(){
  var d = Date.UTC(2026, 9, 13, 0, 0, 0);   // 2026-10-13 00:00 UTC
  function at(h, m){ return (d + (h * 60 + m) * 60000) / 1000; }
  function row(t){ return { time:t, open:100, high:101, low:99, close:100.5, volume:1 }; }
  var now = Date.UTC(2026, 9, 13, 11, 0, 0);
  var r = validateCandles([ row(at(3, 45)), row(at(4, 0)), row(at(3, 40)), row(at(9, 59)), row(at(10, 0)), row(at(3, 47)) ], "15m", now);
  // 03:45 UTC = 09:15 IST ok, 04:00 UTC = 09:30 IST ok, 03:40 UTC = 09:10 IST pre-open,
  // 09:59 UTC = 15:29 IST (misaligned), 10:00 UTC = 15:30 IST (not inside session), 03:47 UTC = 09:17 misaligned
  assert.equal(r.candles.length, 2); assert.equal(r.rejected.offSession, 2); assert.equal(r.rejected.misaligned, 2);
  assert.equal(istLabel(r.candles[0].startMs), "13 Oct 2026, 09:15 IST");
});
test("10b. weekends and NSE holidays are not trading days", function(){
  var sat = Date.UTC(2026, 9, 17, 4, 0, 0) / 1000, hol = Date.UTC(2026, 9, 2, 4, 0, 0) / 1000;   // Gandhi Jayanti 2026-10-02
  var now = Date.UTC(2026, 9, 20, 6, 0, 0);
  var r = validateCandles([{ time:sat, open:1, high:2, low:1, close:1.5, volume:1 }, { time:hol, open:1, high:2, low:1, close:1.5, volume:1 }], "15m", now);
  assert.equal(r.candles.length, 0); assert.equal(r.rejected.offSession, 2);
  var d = validateCandles([{ time:sat, open:1, high:2, low:1, close:1.5, volume:1 }], "1D", now);
  assert.equal(d.rejected.offSession, 1);
});
test("10c. candle completion uses the IST session close (daily 15:30, last 1H candle capped at 15:30)", function(){
  var openDay = Date.UTC(2026, 9, 13, 3, 45, 0);                 // 09:15 IST
  var daily = { time:openDay / 1000, open:100, high:105, low:99, close:104, volume:1 };
  var before = validateCandles([daily], "1D", Date.UTC(2026, 9, 13, 9, 30, 0));   // 15:00 IST
  assert.equal(before.candles[0].endMs, Date.UTC(2026, 9, 13, 10, 0, 0));
  var last1h = { time:Date.UTC(2026, 9, 13, 9, 45, 0) / 1000, open:100, high:105, low:99, close:104, volume:1 };   // 15:15 IST
  var v = validateCandles([last1h], "1H", Date.UTC(2026, 9, 13, 10, 5, 0));
  assert.equal(v.candles.length, 1, "15:15 is on the 1H boundary measured from 09:15");
  assert.equal(v.candles[0].endMs, Date.UTC(2026, 9, 13, 10, 0, 0), "ends at 15:30, not 16:15");
  // completed at 15:30, not at 15:20 (checked through the analyser)
  var cs = candles("1H", 40, up, { now:Date.UTC(2026, 9, 13, 9, 50, 0) });     // 15:20 IST
  var fr = frame(NIFTY, "1H", cs.concat([last1h]));
  var a = analyseFrame(fr, "1H", "higher", NIFTY, Date.UTC(2026, 9, 13, 9, 50, 0));
  assert.ok(a.provisional && a.provisional.startMs == last1h.time * 1000, "15:15 candle still forming at 15:20");
  var b = analyseFrame(fr, "1H", "higher", NIFTY, Date.UTC(2026, 9, 13, 10, 0, 30));
  assert.equal(b.provisional, null); assert.equal(b.last.startMs, last1h.time * 1000);
});
test("10d. instrument, exchange, interval and timezone mismatches are ignored, never mixed", function(){
  var cs = candles("15m", 40, flatThenBreak(1));
  function mk(over){ var f = frame(NIFTY, "15m", cs); Object.assign(f.meta, over); return analyseFrame(f, "15m", "selected", NIFTY, NOW); }
  assert.equal(mk({}).status, "ok");
  ["symbol:BANKNIFTY", "exchangeSegment:NSE_EQ", "timeframe:5", "timezone:UTC", "source:yahoo"].forEach(function(p){
    var kv = p.split(":"), o = {}; o[kv[0]] = kv[1];
    var a = mk(o); assert.equal(a.status, "unavailable", p); assert.equal(a.reasonKey, "bt.tf.mismatch");
  });
  assert.equal(INSTRUMENTS.SENSEX.exchange, "BSE"); assert.equal(INSTRUMENTS.NIFTY.exchange, "NSE");
  var s = evaluateBreakoutTf({ symbol:"SENSEX", tf:"15m", frames:{ "15m":frame("SENSEX", "15m", cs), "1H":frame("SENSEX", "1H", candles("1H", 40, up)), "1D":frame("SENSEX", "1D", candles("1D", 40, up)) }, now:NOW });
  assert.equal(s.exchange, "BSE"); assert.equal(s.state, "confirmed");
  var mixed = evaluateBreakoutTf({ symbol:"SENSEX", tf:"15m", frames:{ "15m":frame("NIFTY", "15m", cs) }, now:NOW });
  assert.equal(mixed.state, "unavailable");
  assert.equal(evaluateBreakoutTf({ symbol:"RELIANCE", tf:"15m", frames:{}, now:NOW }).state, "unavailable");
  assert.equal(evaluateBreakoutTf({ symbol:NIFTY, tf:"10m", frames:{}, now:NOW }).state, "unavailable");
});

