test("11c. Next Move output is deterministic and the level rule matches the existing engine on the same bars", function(){
  var kinds = ["rangeBreakUp", "rangeBreakDown", "range", "up", "down"];
  kinds.forEach(function(k){
    var p = makePayload({ niftyKind:k, bnKind:k, session:"CLOSED", status:"DELAYED" });
    var a = computeNextMove(computeDirection(p, { now:Date.UTC(2026, 9, 13, 5, 0, 0), lastUpdated:Date.UTC(2026, 9, 13, 5, 0, 0) - 5000 }));
    var b = computeNextMove(computeDirection(p, { now:Date.UTC(2026, 9, 13, 5, 0, 0), lastUpdated:Date.UTC(2026, 9, 13, 5, 0, 0) - 5000 }));
    assert.equal(JSON.stringify(a), JSON.stringify(b));
    var bars = makeBars(k, 60, 24000).map(function(x){ return { high:x.h, low:x.l, close:x.c }; });
    var mine = levelAndBreakout(bars, null);
    var bnd = a.scenarios && a.scenarios.bull ? a.scenarios.bull.boundary : null;
    assert.ok(bnd && bnd.resistance != null && bnd.support != null, k + ": Next Move exposes its boundary");
    assert.equal(mine.resistance, bnd.resistance, k + " resistance parity");
    assert.equal(mine.support, bnd.support, k + " support parity");
  });
});
