// ---- invariants: stale / missing / bad data can never be Confirmed ------------------------------
test("invariant: confirmed requires fresh, sufficient, completed-candle data on every required timeframe", function(){
  var good = scenario(1, "up", "up");
  assert.equal(ev("15m", good).state, "confirmed");
  var mutations = {
    noSelected:function(f){ delete f["15m"]; }, noH1:function(f){ delete f["1H"]; }, noD1:function(f){ delete f["1D"]; },
    errH1:function(f){ f["1H"] = { ok:false, error:{ code:"TIMEOUT" } }; },
    staleSel:function(f){ f["15m"] = frame(NIFTY, "15m", candles("15m", 40, flatThenBreak(1), { shiftMs:2 * 3600000 })); },
    shortH1:function(f){ f["1H"] = frame(NIFTY, "1H", candles("1H", 12, up)); },
    wrongSym:function(f){ f["1D"].meta.symbol = "BANKNIFTY"; },
    garbageD1:function(f){ f["1D"] = frame(NIFTY, "1D", [null, 1, "x"]); }
  };
  Object.keys(mutations).forEach(function(m){
    var f = scenario(1, "up", "up"); mutations[m](f);
    var v = ev("15m", f);
    assert.notEqual(v.state, "confirmed", m);
  });
  // the only provisional candle that exists must not turn a waiting view into a confirmed one
  var f2 = scenario(1, "up", "up");
  f2["15m"] = frame(NIFTY, "15m", candles("15m", 40, function(i){ return 100 + wave[i % wave.length]; }, { provisional:140 }));
  assert.notEqual(ev("15m", f2).state, "confirmed");
});
test("invariant: output carries source honesty (not live-verified) and IST timestamps", function(){
  var v = ev("15m", scenario(1, "up", "up"));
  assert.equal(v.source.liveVerified, false); assert.equal(v.source.name, "Dhan");
  assert.match(v.lastCandle.label, /IST$/);
});

