test("english i18n pack has every bt key the engine and screen use; other packs fall back to English", async function(){
  var en = (await import("../src/i18n/lang/en.js")).default.strings;
  var src = read("src/screens/BreakoutTfEngine.js") + read("src/screens/BreakoutTimeframe.jsx");
  var used = {};
  (src.match(/"bt\.[a-z0-9_.]+"/g) || []).forEach(function(k){ used[k.slice(1, -1)] = 1; });
  ["bt.state.", "bt.dir.", "bt.htf."].forEach(function(p){ ["confirmed", "conflicting", "waiting", "unconfirmed", "unavailable", "bullish", "bearish", "none", "neutral", "insufficient", "stale", "error", "unsupported"].forEach(function(x){ if(en[p + x]) used[p + x] = 1; }); });
  for(var i = 1; i <= 6; i++) used["bt.rule." + i] = 1;
  Object.keys(used).forEach(function(k){ if(k == "bt." || /\.$/.test(k)) return; assert.ok(en[k], "missing en key " + k); });
});
